mapper.select:
select * from rag_tasks
where id = #{id} and tenant_id = #{tenantId}
limit 1

select * from rag_tasks
where status = #{status}
order by created_at asc
limit #{limit}

select * from rag_tasks
where status = #{status}
  and locked_at is not null
  and locked_at < #{threshold}
order by locked_at asc
limit #{limit}
